const TTL_MS = 10 * 60 * 1000;
const item = $input.first().json;
const headers = item.headers || {};
const store = $getWorkflowStaticData('global');
if (!store.jobs || typeof store.jobs !== 'object') store.jobs = {};
const now = Date.now();
for (const id of Object.keys(store.jobs)) {
  if (!store.jobs[id] || now - Number(store.jobs[id].at || 0) > TTL_MS) delete store.jobs[id];
}
function header(name) {
  const want = name.toLowerCase();
  for (const key of Object.keys(headers)) {
    if (String(key).toLowerCase() === want) {
      const value = headers[key];
      return Array.isArray(value) ? String(value[0] || '') : String(value == null ? '' : value);
    }
  }
  return '';
}
function same(got, expected) {
  if (!expected || got.length !== expected.length) return false;
  let diff = 0;
  for (let i = 0; i < expected.length; i++) diff |= got.charCodeAt(i) ^ expected.charCodeAt(i);
  return diff === 0;
}
const secret = String($env.KIKO_RELAY_POST_KEY || '');
if (!same(header('authorization'), secret ? ('Bearer ' + secret) : '')) {
  return [{ json: { statusCode: 401, responseBody: { error: 'unauthorized' } } }];
}
const body = item.body && typeof item.body === 'object' ? item.body : {};
const jobId = String(body.job_id || '').trim();
const speech = typeof body.speech === 'string' ? body.speech.trim() : '';
if (!jobId || !speech) {
  return [{ json: { statusCode: 400, responseBody: { error: 'job_id and speech required' } } }];
}
if (speech.length > 8000) {
  return [{ json: { statusCode: 413, responseBody: { error: 'speech too long' } } }];
}
store.jobs[jobId] = { speech: speech, at: now };
return [{ json: { statusCode: 200, responseBody: { ok: true } } }];

